--
-- Table structure for table `socket_message`
--

DROP TABLE IF EXISTS `socket_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `socket_message` (
  `id` bigint NOT NULL COMMENT '主键',
  `sender_id` bigint NOT NULL COMMENT '发送消息的用户id',
  `receiver_id` bigint NOT NULL COMMENT '接收消息的用户id',
  `channel` tinyint DEFAULT NULL COMMENT '消息所在频道(0:系统频道,1:公共频道...)',
  `message_provider` tinyint NOT NULL COMMENT '消息提供者(0:user,1:system,2:ai....)',
  `service_provider` tinyint DEFAULT NULL COMMENT '服务提供者(0:chat_room,1:data_dashboard...)',
  `is_read` tinyint(1) DEFAULT '0' COMMENT '是否读取(1：是 , 0 : 否)',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容',
  `is_send` tinyint(1) DEFAULT '0' COMMENT '是否发送(1: 是，0：否)',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误信息',
  `create_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '发送时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sender_receiver_time` (`sender_id`,`receiver_id`,`create_time`) USING BTREE COMMENT '聚合索引  sender  receiver time ',
  KEY `idx_receiver_sender_time` (`receiver_id`,`sender_id`,`create_time`) USING BTREE COMMENT '聚合索引 receiver  sender time '
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='websocket消息记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

